INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$0014477f$SATQ$, $SATQ$ad0501da-4d14-4062-b511-553221bbccae$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Total Areas of Five Pueblo Nations in New Mexico</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Tribal nation</th><th scope="col" style="text-align: center;vertical-align: bottom;">Area (square miles)</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">Pueblo de San Ildefonso</th><td style="text-align: center;">47.3</td></tr><tr><th scope="row" style="text-align: left;">Santa Clara Pueblo</th><td style="text-align: center;">77.1</td></tr><tr><th scope="row" style="text-align: left;">Taos Pueblo</th><td style="text-align: center;">156.2</td></tr><tr><th scope="row" style="text-align: left;">Namb&eacute; Pueblo</th><td style="text-align: center;">32.4</td></tr><tr><th scope="row" style="text-align: left;">Pueblo of Acoma</th><td style="text-align: center;">595.7</td></tr></tbody></table></figure></p>
<p>There are nineteen Pueblo tribal nations in New Mexico. A student in a geography class is a citizen of Taos Pueblo in the northern part of the state. The student wants to compare the total area covered by Taos Pueblo with the total areas of various other Pueblo nations in the state. Looking at the table, the student finds that the total area of Taos Pueblo is 156.2 square miles, while the total area of Namb&eacute; Pueblo is <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the comparison?</p>$SATQ$, $SATQ$[{"id":"fbb0fefd-28ce-4438-b383-7e5cacedc3ff","content":"<p>47.3 square miles.</p>"},{"id":"1b43a8d7-f606-490d-8196-a0a179fc3223","content":"<p>77.1 square miles.</p>"},{"id":"f3e1d197-c32d-4650-8671-91c2b0c7c068","content":"<p>32.4 square miles.</p>"},{"id":"19c0812d-d227-4ed0-a770-6f1b73ccac9b","content":"<p>595.7 square miles.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["f3e1d197-c32d-4650-8671-91c2b0c7c068"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most effectively uses data from the table to complete the comparison between Pueblo tribal nations. The student identifies that the total area of Taos Pueblo is 156.2 square miles and needs to complete the comparison with the total area of Namb&eacute; Pueblo. According to the table, Namb&eacute; Pueblo has a total area of 32.4 square miles.</p><p>Choice A is incorrect because according to the table, 47.3 square miles is the area of Pueblo de San Ildefonso, not of Namb&eacute; Pueblo. Choice B is incorrect because according to the table, 77.1 square miles is the area of Santa Clara Pueblo, not of Namb&eacute; Pueblo. Choice D is incorrect because according to the table, 595.7 square miles is the area of Pueblo of Acoma, not of Namb&eacute; Pueblo.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"0014477f","external_id":"ad0501da-4d14-4062-b511-553221bbccae","vaultid":null,"uId":"da67633d-fdf1-454c-b282-96fddd4aba9f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Total Areas of Five Pueblo Nations in New Mexico</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Tribal nation</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Area (square miles)</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">Pueblo de San Ildefonso</th><td style=\"text-align: center;\">47.3</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Santa Clara Pueblo</th><td style=\"text-align: center;\">77.1</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Taos Pueblo</th><td style=\"text-align: center;\">156.2</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Namb&eacute; Pueblo</th><td style=\"text-align: center;\">32.4</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Pueblo of Acoma</th><td style=\"text-align: center;\">595.7</td></tr></tbody></table></figure></p>\n<p>There are nineteen Pueblo tribal nations in New Mexico. A student in a geography class is a citizen of Taos Pueblo in the northern part of the state. The student wants to compare the total area covered by Taos Pueblo with the total areas of various other Pueblo nations in the state. Looking at the table, the student finds that the total area of Taos Pueblo is 156.2 square miles, while the total area of Namb&eacute; Pueblo is <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most effectively uses data from the table to complete the comparison?</p>","answerOptions":[{"id":"fbb0fefd-28ce-4438-b383-7e5cacedc3ff","content":"<p>47.3 square miles.</p>"},{"id":"1b43a8d7-f606-490d-8196-a0a179fc3223","content":"<p>77.1 square miles.</p>"},{"id":"f3e1d197-c32d-4650-8671-91c2b0c7c068","content":"<p>32.4 square miles.</p>"},{"id":"19c0812d-d227-4ed0-a770-6f1b73ccac9b","content":"<p>595.7 square miles.</p>"}],"keys":["f3e1d197-c32d-4650-8671-91c2b0c7c068"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most effectively uses data from the table to complete the comparison between Pueblo tribal nations. The student identifies that the total area of Taos Pueblo is 156.2 square miles and needs to complete the comparison with the total area of Namb&eacute; Pueblo. According to the table, Namb&eacute; Pueblo has a total area of 32.4 square miles.</p><p>Choice A is incorrect because according to the table, 47.3 square miles is the area of Pueblo de San Ildefonso, not of Namb&eacute; Pueblo. Choice B is incorrect because according to the table, 77.1 square miles is the area of Santa Clara Pueblo, not of Namb&eacute; Pueblo. Choice D is incorrect because according to the table, 595.7 square miles is the area of Pueblo of Acoma, not of Namb&eacute; Pueblo.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061190,"updateDate":1755117061190}$SATQ$::jsonb, 1755117061190, 1755117061190),
    ($SATQ$0021d326$SATQ$, $SATQ$cdec6f45-f788-41ed-b5ca-a993c1daa960$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Olms are salamanders that live in underwater caves. Scientists once thought that olms stay in their caves all their lives. However, Raoul Manenti and team claim that <span style="text-decoration: underline;" role="region" aria-label="Referenced Content">olms regularly come to the surface to perform important activities such as finding food.</span></p>$SATQ$, $SATQ$<p>Which finding, if true, would most strongly support the underlined claim?</p>$SATQ$, $SATQ$[{"id":"8613bf71-2832-4a6e-a8b7-eca20634e767","content":"<p>Researchers determine that olms don&rsquo;t breed often.</p>"},{"id":"94040776-a669-488e-8b5f-8c6cde616e12","content":"<p>Researchers confirm that olms live in only a few cave systems.</p>"},{"id":"2ecb7ac8-6d8d-4a39-a549-b449ced71d2e","content":"<p>Researchers discover that earthworms from surface soils are a major part of olms&rsquo; diet.</p>"},{"id":"e40aecd3-bdb6-4919-a7fe-e30b8107776a","content":"<p>Researchers learn that olms&rsquo; brains differ from other salamanders&rsquo; brains.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["2ecb7ac8-6d8d-4a39-a549-b449ced71d2e"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it presents a finding that, if true, would most strongly support Manenti and team&rsquo;s claim that olms regularly come to the surface to find food. The text explains that scientists previously believed olms remained in their underwater caves throughout their lives, but Manenti&rsquo;s team claims that olms actually surface regularly to perform important activities like finding food. Since earthworms from surface soils would not be present in underwater caves, the finding that such earthworms constitute a major part of olms&rsquo; diet would provide compelling evidence that olms regularly leave their underwater cave environment to obtain food from the surface, thus supporting the underlined claim.</p><p>Choice A is incorrect because information about olms&rsquo; breeding frequency wouldn&rsquo;t support the claim about their leaving their underwater habitats to obtain food. While breeding patterns might be relevant to understanding olm behavior in general, this finding doesn&rsquo;t address whether olms surface to find food, which is the specific behavior that the underlined claim addresses. Choice B is incorrect because learning that olms live in only a few cave systems wouldn&rsquo;t support the claim about their regular visits to the surface. This finding would provide information about the geographic distribution of olm habitats but wouldn&rsquo;t address whether olms leave these caves to find food or perform other activities on the surface. Choice D is incorrect because the differences between olms&rsquo; brains and other salamanders&rsquo; brains have no clear connection to olms&rsquo; movement beyond their underwater habitats or to their feeding habits. A finding about the uniqueness of olms&rsquo; brains wouldn&rsquo;t address whether olms leave their caves to find food or support Manenti and team&rsquo;s claim about olms&rsquo; motivation for coming to the surface.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"0021d326","external_id":"cdec6f45-f788-41ed-b5ca-a993c1daa960","vaultid":null,"uId":"e4f2161f-37b4-4de4-93f6-1c454bd558d9","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Olms are salamanders that live in underwater caves. Scientists once thought that olms stay in their caves all their lives. However, Raoul Manenti and team claim that <span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">olms regularly come to the surface to perform important activities such as finding food.</span></p>","stem":"<p>Which finding, if true, would most strongly support the underlined claim?</p>","answerOptions":[{"id":"8613bf71-2832-4a6e-a8b7-eca20634e767","content":"<p>Researchers determine that olms don&rsquo;t breed often.</p>"},{"id":"94040776-a669-488e-8b5f-8c6cde616e12","content":"<p>Researchers confirm that olms live in only a few cave systems.</p>"},{"id":"2ecb7ac8-6d8d-4a39-a549-b449ced71d2e","content":"<p>Researchers discover that earthworms from surface soils are a major part of olms&rsquo; diet.</p>"},{"id":"e40aecd3-bdb6-4919-a7fe-e30b8107776a","content":"<p>Researchers learn that olms&rsquo; brains differ from other salamanders&rsquo; brains.</p>"}],"keys":["2ecb7ac8-6d8d-4a39-a549-b449ced71d2e"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it presents a finding that, if true, would most strongly support Manenti and team&rsquo;s claim that olms regularly come to the surface to find food. The text explains that scientists previously believed olms remained in their underwater caves throughout their lives, but Manenti&rsquo;s team claims that olms actually surface regularly to perform important activities like finding food. Since earthworms from surface soils would not be present in underwater caves, the finding that such earthworms constitute a major part of olms&rsquo; diet would provide compelling evidence that olms regularly leave their underwater cave environment to obtain food from the surface, thus supporting the underlined claim.</p><p>Choice A is incorrect because information about olms&rsquo; breeding frequency wouldn&rsquo;t support the claim about their leaving their underwater habitats to obtain food. While breeding patterns might be relevant to understanding olm behavior in general, this finding doesn&rsquo;t address whether olms surface to find food, which is the specific behavior that the underlined claim addresses. Choice B is incorrect because learning that olms live in only a few cave systems wouldn&rsquo;t support the claim about their regular visits to the surface. This finding would provide information about the geographic distribution of olm habitats but wouldn&rsquo;t address whether olms leave these caves to find food or perform other activities on the surface. Choice D is incorrect because the differences between olms&rsquo; brains and other salamanders&rsquo; brains have no clear connection to olms&rsquo; movement beyond their underwater habitats or to their feeding habits. A finding about the uniqueness of olms&rsquo; brains wouldn&rsquo;t address whether olms leave their caves to find food or support Manenti and team&rsquo;s claim about olms&rsquo; motivation for coming to the surface.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771170,"updateDate":1776362771170}$SATQ$::jsonb, 1776362771170, 1776362771170),
    ($SATQ$0045c234$SATQ$, $SATQ$de524c7e-6530-4cc4-889d-5f33fb362adc$SATQ$::uuid, $SATQ$5905eed5-41ea-42ee-8cd4-b3a88dfc46e1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Given that stars and planets initially form from the same gas and dust in space, some astronomers have posited that host stars (such as the Sun) and their planets (such as those in our solar system) are composed of the same materials, with the planets containing equal or smaller quantities of the materials that make up the host star. This idea is also supported by evidence that rocky planets in our solar system are composed of some of the same materials as the Sun.</p>$SATQ$, $SATQ$<p>Which finding, if true, would most directly weaken the astronomers&rsquo; claim?</p>$SATQ$, $SATQ$[{"id":"76d16ef9-21e6-4f2a-b39c-d0716b83528d","content":"<p>Most stars are made of hydrogen and helium, but when cooled they are revealed to contain small amounts of iron and silicate.</p>"},{"id":"1089547d-ad67-4563-a2d9-db71371bd3ed","content":"<p>A nearby host star is observed to contain the same proportion of hydrogen and helium as that of the Sun.</p>"},{"id":"26e0b6c4-6b92-49f9-93d3-6ab71414e13e","content":"<p>Evidence emerges that the amount of iron in some rocky planets is considerably higher than the amount in their host star.</p>"},{"id":"d2e51c97-295a-47f6-9111-34a038569286","content":"<p>The method for determining the composition of rocky planets is discovered to be less effective when used to analyze other kinds of planets.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["26e0b6c4-6b92-49f9-93d3-6ab71414e13e"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it presents a finding that, if true, would weaken the astronomers&rsquo; claim about the makeup of host stars and their planets. The text explains that because stars and planets begin forming from the same gas and dust, astronomers believe planets should be composed of the same materials as their host stars, but in equal or smaller quantities. The finding that the amount of iron in some rocky planets is much higher than the amount in their host star would weaken the astronomers&rsquo; claim because it would show that some planets contain the same material as their host star, but in higher quantities. </p><p>Choice A is incorrect because a finding only about the makeup of stars, whether they&rsquo;ve cooled or not, would provide no information about the makeup of planets. Thus, it wouldn&rsquo;t have any bearing on the claim that planets and their host stars are composed of the same materials in differing quantities. Choice B is incorrect because a finding about two host stars having similar proportions of certain materials wouldn&rsquo;t provide any information about the makeup of planets. Thus, it wouldn&rsquo;t be relevant to the claim that planets and their host stars are composed of the same materials in differing quantities. Choice D is incorrect because the text indicates that the astronomers&rsquo; claim is based on a fact&mdash;that stars and planets begin forming from the same gas and dust in space&mdash;which would remain true regardless of the effectiveness of a method for analysis of compositions. The text does cite analysis of rocky planets in our solar system and the Sun, but only as a single piece of evidence that is consistent with the claim and not as the source of the claim; the finding that the method used for that analysis is less effective in other scenarios wouldn&rsquo;t weaken a claim that&rsquo;s based on knowledge of how stars and planets initially form. </p>$SATQ$, false, 0, $SATQ$OSP-320-TXT$SATQ$, $SATQ$$SATQ$, $SATQ$41779965-3f31-4197-8af5-ffa5a17bfae1$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"0045c234","external_id":"de524c7e-6530-4cc4-889d-5f33fb362adc","vaultid":"5905eed5-41ea-42ee-8cd4-b3a88dfc46e1","uId":"ee6a5d4d-6c43-47c5-96bd-629d6b5f18c2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Given that stars and planets initially form from the same gas and dust in space, some astronomers have posited that host stars (such as the Sun) and their planets (such as those in our solar system) are composed of the same materials, with the planets containing equal or smaller quantities of the materials that make up the host star. This idea is also supported by evidence that rocky planets in our solar system are composed of some of the same materials as the Sun.</p>","stem":"<p>Which finding, if true, would most directly weaken the astronomers&rsquo; claim?</p>","answerOptions":[{"id":"76d16ef9-21e6-4f2a-b39c-d0716b83528d","content":"<p>Most stars are made of hydrogen and helium, but when cooled they are revealed to contain small amounts of iron and silicate.</p>"},{"id":"1089547d-ad67-4563-a2d9-db71371bd3ed","content":"<p>A nearby host star is observed to contain the same proportion of hydrogen and helium as that of the Sun.</p>"},{"id":"26e0b6c4-6b92-49f9-93d3-6ab71414e13e","content":"<p>Evidence emerges that the amount of iron in some rocky planets is considerably higher than the amount in their host star.</p>"},{"id":"d2e51c97-295a-47f6-9111-34a038569286","content":"<p>The method for determining the composition of rocky planets is discovered to be less effective when used to analyze other kinds of planets.</p>"}],"keys":["26e0b6c4-6b92-49f9-93d3-6ab71414e13e"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it presents a finding that, if true, would weaken the astronomers&rsquo; claim about the makeup of host stars and their planets. The text explains that because stars and planets begin forming from the same gas and dust, astronomers believe planets should be composed of the same materials as their host stars, but in equal or smaller quantities. The finding that the amount of iron in some rocky planets is much higher than the amount in their host star would weaken the astronomers&rsquo; claim because it would show that some planets contain the same material as their host star, but in higher quantities. </p><p>Choice A is incorrect because a finding only about the makeup of stars, whether they&rsquo;ve cooled or not, would provide no information about the makeup of planets. Thus, it wouldn&rsquo;t have any bearing on the claim that planets and their host stars are composed of the same materials in differing quantities. Choice B is incorrect because a finding about two host stars having similar proportions of certain materials wouldn&rsquo;t provide any information about the makeup of planets. Thus, it wouldn&rsquo;t be relevant to the claim that planets and their host stars are composed of the same materials in differing quantities. Choice D is incorrect because the text indicates that the astronomers&rsquo; claim is based on a fact&mdash;that stars and planets begin forming from the same gas and dust in space&mdash;which would remain true regardless of the effectiveness of a method for analysis of compositions. The text does cite analysis of rocky planets in our solar system and the Sun, but only as a single piece of evidence that is consistent with the claim and not as the source of the claim; the finding that the method used for that analysis is less effective in other scenarios wouldn&rsquo;t weaken a claim that&rsquo;s based on knowledge of how stars and planets initially form. </p>","parenttemplatename":"OSP-320-TXT","parenttemplateid":"","templateclusterid":"41779965-3f31-4197-8af5-ffa5a17bfae1","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959335,"updateDate":1691007959335}$SATQ$::jsonb, 1691007959335, 1691007959335),
    ($SATQ$010fa3f0$SATQ$, $SATQ$6537fc25-1318-49e9-9e1e-dcc07604c519$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Simulated Change in Annual Aquifer Input and Irrigation Output if Precipitation Concentration Increases as Climate Models Predict</p></caption><thead><tr><th scope="col" style="text-align: center; vertical-align: bottom;">Baseline concentration of annual precipitation</th><th scope="col" style="text-align: center; vertical-align: bottom;">% change in water entering aquifers</th><th scope="col" style="text-align: center; vertical-align: bottom;">% change in surface water used for irrigation</th><th scope="col" style="text-align: center; vertical-align: bottom;">% change in groundwater used for irrigation</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">Precipitation is currently somewhat concentrated</th><td style="text-align: center;">4.9</td><td style="text-align: center;">0.4</td><td style="text-align: center;">0.9</td></tr><tr><th scope="row" style="text-align: left;">Precipitation is currently evenly distributed</th><td style="text-align: center;">11.0</td><td style="text-align: center;">9.0</td><td style="text-align: center;">7.9</td></tr></tbody></table></figure></p>
<p>Some climate models for the western United States predict that while total annual precipitation may remain unchanged from the present level, precipitation will become concentrated into fewer but more intense rain and snow events. University of Texas climate scientist Geeta Persad and her colleagues simulated how the amount of water entering aquifers and the amount being used for irrigation purposes would change if this were to occur. Persad and her colleagues concluded that concentration of precipitation into fewer events would result in a higher number of dry days, triggering more irrigation, but that this change in irrigation output is highly sensitive to the baseline concentration of precipitation that currently exists in an area.</p>$SATQ$, $SATQ$<p>Which choice best describes data from the table that support Persad and her colleagues&rsquo; conclusion?</p>$SATQ$, $SATQ$[{"id":"4c4809cb-1ee7-4e89-beda-abd7ff8f1b35","content":"<p>If baseline precipitation is somewhat concentrated, the amount of water being used for irrigation will increase 0.4% for surface water and 0.9% for groundwater, whereas the amount of water entering aquifers will increase 11.0% if baseline precipitation is evenly distributed.&nbsp;</p>"},{"id":"4f79e237-d4a9-403a-a18c-e18b21972838","content":"<p>If baseline precipitation is somewhat concentrated, water use for irrigation will increase only slightly, whereas it will increase 9.0% for surface water and 7.9% for groundwater if baseline precipitation is evenly distributed.</p>"},{"id":"6991d531-fdaa-44e1-bbd8-0e4f6536b445","content":"<p>If baseline precipitation is somewhat concentrated, the amount of water entering aquifers will increase 4.9%, while the amount being used for irrigation will increase 0.4% for surface water and 0.9% for groundwater.&nbsp;</p>"},{"id":"90729294-9741-4c4b-b4e0-bd7dcaca77a2","content":"<p>If baseline precipitation is somewhat concentrated, water use for irrigation will decline by a small amount, whereas it will increase 11.0% for surface water and 9.0% for groundwater if baseline precipitation is evenly distributed.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["4f79e237-d4a9-403a-a18c-e18b21972838"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it describes data from the table that support Persad and her colleagues&rsquo; conclusion. The text explains that, according to some climate models, precipitation in the western United States will become concentrated into fewer, more intense rain and snow events. According to the text, Persad and her colleagues concluded that more irrigation will consequently be needed but that the change in irrigation output will be highly sensitive to, or greatly affected by, the baseline concentration of precipitation in an area. This conclusion is supported by data from the researchers&rsquo; simulations of changes in annual irrigation output in two different scenarios&mdash;one in which an area&rsquo;s annual precipitation is already somewhat concentrated and one in which its annual precipitation is evenly distributed. The table shows that if baseline precipitation is somewhat concentrated, water use for irrigation will increase only slightly, whereas if baseline precipitation is evenly distributed, water use for irrigation will increase much more&mdash;9.0% for surface water and 7.9% for groundwater. This difference illustrates the researchers&rsquo; conclusion that the amount of additional water needed for irrigation will vary greatly depending on how concentrated or spread out the annual precipitation in an area already is.</p><p>Choice A is incorrect because it compares changes in the amount of water being used for irrigation to changes in the amount of water entering aquifers. Persad and her colleagues&rsquo; conclusion doesn&rsquo;t focus on changes to the amount of water entering aquifers; rather, the researchers&rsquo; conclusion focuses on changes to irrigation output relative to how concentrated or spread out the annual precipitation in an area is. Choice C is incorrect because it supports only part of Persad and her colleagues&rsquo; conclusion. According to the text, the researchers concluded that the concentration of precipitation into fewer events will trigger more irrigation but that this change in irrigation output will be highly sensitive to an area&rsquo;s baseline concentration of annual precipitation. The data in this choice support the idea that more irrigation will be needed, but to support the rest of the researchers&rsquo; conclusion, additional data from the table are required to show that the increases in water use for irrigation will vary depending on how concentrated or spread out the annual precipitation in an area already is. Choice D is incorrect because data in the table indicate no declines in water use for irrigation, showing only increases in the form of positive values.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"010fa3f0","external_id":"6537fc25-1318-49e9-9e1e-dcc07604c519","vaultid":null,"uId":"a84c31f8-bd49-46eb-8737-d03c9421329c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Simulated Change in Annual Aquifer Input and Irrigation Output if Precipitation Concentration Increases as Climate Models Predict</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Baseline concentration of annual precipitation</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">% change in water entering aquifers</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">% change in surface water used for irrigation</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">% change in groundwater used for irrigation</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">Precipitation is currently somewhat concentrated</th><td style=\"text-align: center;\">4.9</td><td style=\"text-align: center;\">0.4</td><td style=\"text-align: center;\">0.9</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Precipitation is currently evenly distributed</th><td style=\"text-align: center;\">11.0</td><td style=\"text-align: center;\">9.0</td><td style=\"text-align: center;\">7.9</td></tr></tbody></table></figure></p>\n<p>Some climate models for the western United States predict that while total annual precipitation may remain unchanged from the present level, precipitation will become concentrated into fewer but more intense rain and snow events. University of Texas climate scientist Geeta Persad and her colleagues simulated how the amount of water entering aquifers and the amount being used for irrigation purposes would change if this were to occur. Persad and her colleagues concluded that concentration of precipitation into fewer events would result in a higher number of dry days, triggering more irrigation, but that this change in irrigation output is highly sensitive to the baseline concentration of precipitation that currently exists in an area.</p>","stem":"<p>Which choice best describes data from the table that support Persad and her colleagues&rsquo; conclusion?</p>","answerOptions":[{"id":"4c4809cb-1ee7-4e89-beda-abd7ff8f1b35","content":"<p>If baseline precipitation is somewhat concentrated, the amount of water being used for irrigation will increase 0.4% for surface water and 0.9% for groundwater, whereas the amount of water entering aquifers will increase 11.0% if baseline precipitation is evenly distributed.&nbsp;</p>"},{"id":"4f79e237-d4a9-403a-a18c-e18b21972838","content":"<p>If baseline precipitation is somewhat concentrated, water use for irrigation will increase only slightly, whereas it will increase 9.0% for surface water and 7.9% for groundwater if baseline precipitation is evenly distributed.</p>"},{"id":"6991d531-fdaa-44e1-bbd8-0e4f6536b445","content":"<p>If baseline precipitation is somewhat concentrated, the amount of water entering aquifers will increase 4.9%, while the amount being used for irrigation will increase 0.4% for surface water and 0.9% for groundwater.&nbsp;</p>"},{"id":"90729294-9741-4c4b-b4e0-bd7dcaca77a2","content":"<p>If baseline precipitation is somewhat concentrated, water use for irrigation will decline by a small amount, whereas it will increase 11.0% for surface water and 9.0% for groundwater if baseline precipitation is evenly distributed.</p>"}],"keys":["4f79e237-d4a9-403a-a18c-e18b21972838"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it describes data from the table that support Persad and her colleagues&rsquo; conclusion. The text explains that, according to some climate models, precipitation in the western United States will become concentrated into fewer, more intense rain and snow events. According to the text, Persad and her colleagues concluded that more irrigation will consequently be needed but that the change in irrigation output will be highly sensitive to, or greatly affected by, the baseline concentration of precipitation in an area. This conclusion is supported by data from the researchers&rsquo; simulations of changes in annual irrigation output in two different scenarios&mdash;one in which an area&rsquo;s annual precipitation is already somewhat concentrated and one in which its annual precipitation is evenly distributed. The table shows that if baseline precipitation is somewhat concentrated, water use for irrigation will increase only slightly, whereas if baseline precipitation is evenly distributed, water use for irrigation will increase much more&mdash;9.0% for surface water and 7.9% for groundwater. This difference illustrates the researchers&rsquo; conclusion that the amount of additional water needed for irrigation will vary greatly depending on how concentrated or spread out the annual precipitation in an area already is.</p><p>Choice A is incorrect because it compares changes in the amount of water being used for irrigation to changes in the amount of water entering aquifers. Persad and her colleagues&rsquo; conclusion doesn&rsquo;t focus on changes to the amount of water entering aquifers; rather, the researchers&rsquo; conclusion focuses on changes to irrigation output relative to how concentrated or spread out the annual precipitation in an area is. Choice C is incorrect because it supports only part of Persad and her colleagues&rsquo; conclusion. According to the text, the researchers concluded that the concentration of precipitation into fewer events will trigger more irrigation but that this change in irrigation output will be highly sensitive to an area&rsquo;s baseline concentration of annual precipitation. The data in this choice support the idea that more irrigation will be needed, but to support the rest of the researchers&rsquo; conclusion, additional data from the table are required to show that the increases in water use for irrigation will vary depending on how concentrated or spread out the annual precipitation in an area already is. Choice D is incorrect because data in the table indicate no declines in water use for irrigation, showing only increases in the form of positive values.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323045,"updateDate":1730147323045}$SATQ$::jsonb, 1730147323045, 1730147323045),
    ($SATQ$0113152f$SATQ$, $SATQ$a42ee406-d532-4af6-bce0-53b4aaf2ec41$SATQ$::uuid, $SATQ$5110cc72-2c4a-416b-b498-fba6bab19753$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>American fashion designer Patrick Kelly was known for his love of colorful buttons. Many of his signature dresses feature bold assortments of buttons throughout the garment. In a paper, a fashion design student claims that Kelly&rsquo;s use of buttons as decoration was inspired by his childhood observations of the styles and actions of the women in his family.</p>$SATQ$, $SATQ$<p>Which quotation from a work by a historian would be the most effective evidence for the student to include in support of this claim?</p>$SATQ$, $SATQ$[{"id":"9d14761c-6d62-4588-87f9-c4f976844b84","content":"<p>&ldquo;Although some of the assortments of buttons appear to be mismatched pieces scattered randomly throughout Kelly&rsquo;s dresses, his most famous designs feature carefully crafted patterns of matching buttons.&rdquo;</p>"},{"id":"252d5118-3c99-4187-920d-e5bb17042236","content":"<p>&ldquo;Many of Kelly&rsquo;s contemporaries were inspired by his designs to incorporate buttons, as well as zippers and snaps, as decorative items in their work.&rdquo;&nbsp;</p>"},{"id":"cdf39c1f-6e6a-439d-b7ec-ea775435cf89","content":"<p>&ldquo;Kelly&rsquo;s grandmother, who would repair clothing when he was a child, frequently added mismatched buttons to the clothes to draw attention away from any flaws in the garments.&rdquo;</p>"},{"id":"b5d2ed3a-dca9-4feb-b138-1f44cc27d06c","content":"<p>&ldquo;Kelly was destined to be a designer from a young age: he learned how to sew clothing from his aunt Bertha, and his love of drawing was developed by his mother.&rdquo;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["cdf39c1f-6e6a-439d-b7ec-ea775435cf89"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. This quotation draws a direct connection between the use of buttons and Kelly&rsquo;s stylish female relatives.</p><p>Choice A is incorrect. This choice mentions Kelly&rsquo;s use of buttons, but it doesn&rsquo;t connect that design choice to the influence of women in Kelly&rsquo;s family. Choice B is incorrect. This choice discusses how other designers were inspired by Kelly, which doesn&rsquo;t provide evidence that Kelly was inspired by his family. Choice D is incorrect. While this choice does refer to fashionable women in Kelly&rsquo;s family, it doesn&rsquo;t connect their influence to Kelly&rsquo;s use of buttons.</p>$SATQ$, false, 0, $SATQ$OSP-KA-TXT-E006$SATQ$, $SATQ$$SATQ$, $SATQ$a67631c5-7adf-48f6-b649-cacc9efaafeb$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"0113152f","external_id":"a42ee406-d532-4af6-bce0-53b4aaf2ec41","vaultid":"5110cc72-2c4a-416b-b498-fba6bab19753","uId":"b579a415-96d3-4c74-a42b-e18c7514cca1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>American fashion designer Patrick Kelly was known for his love of colorful buttons. Many of his signature dresses feature bold assortments of buttons throughout the garment. In a paper, a fashion design student claims that Kelly&rsquo;s use of buttons as decoration was inspired by his childhood observations of the styles and actions of the women in his family.</p>","stem":"<p>Which quotation from a work by a historian would be the most effective evidence for the student to include in support of this claim?</p>","answerOptions":[{"id":"9d14761c-6d62-4588-87f9-c4f976844b84","content":"<p>&ldquo;Although some of the assortments of buttons appear to be mismatched pieces scattered randomly throughout Kelly&rsquo;s dresses, his most famous designs feature carefully crafted patterns of matching buttons.&rdquo;</p>"},{"id":"252d5118-3c99-4187-920d-e5bb17042236","content":"<p>&ldquo;Many of Kelly&rsquo;s contemporaries were inspired by his designs to incorporate buttons, as well as zippers and snaps, as decorative items in their work.&rdquo;&nbsp;</p>"},{"id":"cdf39c1f-6e6a-439d-b7ec-ea775435cf89","content":"<p>&ldquo;Kelly&rsquo;s grandmother, who would repair clothing when he was a child, frequently added mismatched buttons to the clothes to draw attention away from any flaws in the garments.&rdquo;</p>"},{"id":"b5d2ed3a-dca9-4feb-b138-1f44cc27d06c","content":"<p>&ldquo;Kelly was destined to be a designer from a young age: he learned how to sew clothing from his aunt Bertha, and his love of drawing was developed by his mother.&rdquo;</p>"}],"keys":["cdf39c1f-6e6a-439d-b7ec-ea775435cf89"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. This quotation draws a direct connection between the use of buttons and Kelly&rsquo;s stylish female relatives.</p><p>Choice A is incorrect. This choice mentions Kelly&rsquo;s use of buttons, but it doesn&rsquo;t connect that design choice to the influence of women in Kelly&rsquo;s family. Choice B is incorrect. This choice discusses how other designers were inspired by Kelly, which doesn&rsquo;t provide evidence that Kelly was inspired by his family. Choice D is incorrect. While this choice does refer to fashionable women in Kelly&rsquo;s family, it doesn&rsquo;t connect their influence to Kelly&rsquo;s use of buttons.</p>","parenttemplatename":"OSP-KA-TXT-E006","parenttemplateid":"","templateclusterid":"a67631c5-7adf-48f6-b649-cacc9efaafeb","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959376,"updateDate":1691007959376}$SATQ$::jsonb, 1691007959376, 1691007959376),
    ($SATQ$0147b080$SATQ$, $SATQ$3a3cd377-09e1-421d-b264-2e6d5797db0a$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Pyramids in Egypt and the Americas</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Pyramid</th><th scope="col" style="text-align: center;vertical-align: bottom;">Country</th><th scope="col" style="text-align: center;vertical-align: bottom;">Height (meters)</th><th scope="col" style="text-align: center;vertical-align: bottom;">Age (years before present)</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">The Great Pyramid</th><td>Mexico</td><td style="text-align: center;">33</td><td style="text-align: center;">2,050 to 2,400</td></tr><tr><th scope="row" style="text-align: left;">The Pyramid of Djoser</th><td>Egypt</td><td style="text-align: center;">60</td><td style="text-align: center;">4,600 to 4,700</td></tr><tr><th scope="row" style="text-align: left;">The Pyramid of Sahure</th><td>Egypt</td><td style="text-align: center;">47</td><td style="text-align: center;">4,400 to 4,500</td></tr><tr><th scope="row" style="text-align: left;">El Castillo</th><td>Belize</td><td style="text-align: center;">40</td><td style="text-align: center;">1,100 to 1,400</td></tr></tbody></table></figure></p>
<p>A student is writing an essay about four pyramids for a history class and wants to note how long ago each pyramid was built and how tall each pyramid is. Consulting the table, the student finds that el Castillo was built 1,100 to 1,400 years ago and is&nbsp; <span aria-hidden="true">______</span><span class="sr-only">blank</span>&nbsp;</p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to complete the text?</p>$SATQ$, $SATQ$[{"id":"d5d45ba6-071e-4f05-a2d9-7ced8d3f56c0","content":"<p>33 meters tall.</p>"},{"id":"6236871e-480d-4c24-99d1-a968aa823a0b","content":"<p>47 meters tall.</p>"},{"id":"3c31f8ca-dad1-46a3-910d-8247750722ef","content":"<p>40 meters tall.</p>"},{"id":"a997bf95-1d81-436e-90b5-296b45e9ed55","content":"<p>60 meters tall.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["3c31f8ca-dad1-46a3-910d-8247750722ef"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most effectively uses data from the table to complete the text about the el Castillo pyramid. The table presents information for the location, height, and age of four pyramids, and the task is to use the data from the table to complete the text by choosing the correct height for el Castillo, which the table shows is 40 meters.</p><p>Choice A is incorrect because, according to the table, el Castillo is 40 meters tall, not 33 meters, which is the height of the Great Pyramid in Mexico. Choice B is incorrect because, according to the table, el Castillo is 40 meters tall, not 47 meters, which is the height of the Pyramid of Sahure in Egypt. Choice D is incorrect because, according to the table, el Castillo is 40 meters tall, not 60 meters, which is the height of the Pyramid of Djoser in Egypt.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"0147b080","external_id":"3a3cd377-09e1-421d-b264-2e6d5797db0a","vaultid":null,"uId":"0cb8566f-f19a-4add-9cec-973ee417f644","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Pyramids in Egypt and the Americas</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Pyramid</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Country</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Height (meters)</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Age (years before present)</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">The Great Pyramid</th><td>Mexico</td><td style=\"text-align: center;\">33</td><td style=\"text-align: center;\">2,050 to 2,400</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">The Pyramid of Djoser</th><td>Egypt</td><td style=\"text-align: center;\">60</td><td style=\"text-align: center;\">4,600 to 4,700</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">The Pyramid of Sahure</th><td>Egypt</td><td style=\"text-align: center;\">47</td><td style=\"text-align: center;\">4,400 to 4,500</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">El Castillo</th><td>Belize</td><td style=\"text-align: center;\">40</td><td style=\"text-align: center;\">1,100 to 1,400</td></tr></tbody></table></figure></p>\n<p>A student is writing an essay about four pyramids for a history class and wants to note how long ago each pyramid was built and how tall each pyramid is. Consulting the table, the student finds that el Castillo was built 1,100 to 1,400 years ago and is&nbsp; <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span>&nbsp;</p>","stem":"<p>Which choice most effectively uses data from the table to complete the text?</p>","answerOptions":[{"id":"d5d45ba6-071e-4f05-a2d9-7ced8d3f56c0","content":"<p>33 meters tall.</p>"},{"id":"6236871e-480d-4c24-99d1-a968aa823a0b","content":"<p>47 meters tall.</p>"},{"id":"3c31f8ca-dad1-46a3-910d-8247750722ef","content":"<p>40 meters tall.</p>"},{"id":"a997bf95-1d81-436e-90b5-296b45e9ed55","content":"<p>60 meters tall.</p>"}],"keys":["3c31f8ca-dad1-46a3-910d-8247750722ef"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most effectively uses data from the table to complete the text about the el Castillo pyramid. The table presents information for the location, height, and age of four pyramids, and the task is to use the data from the table to complete the text by choosing the correct height for el Castillo, which the table shows is 40 meters.</p><p>Choice A is incorrect because, according to the table, el Castillo is 40 meters tall, not 33 meters, which is the height of the Great Pyramid in Mexico. Choice B is incorrect because, according to the table, el Castillo is 40 meters tall, not 47 meters, which is the height of the Pyramid of Sahure in Egypt. Choice D is incorrect because, according to the table, el Castillo is 40 meters tall, not 60 meters, which is the height of the Pyramid of Djoser in Egypt.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061177,"updateDate":1755117061177}$SATQ$::jsonb, 1755117061177, 1755117061177),
    ($SATQ$014b3394$SATQ$, $SATQ$e46bbf40-c607-49b6-b493-1fb84005ae31$SATQ$::uuid, $SATQ$8fa2cec9-59e4-4fbd-9b8f-e9cc1673026f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Average Number and Duration of Torpor Bouts and Arousal Episodes for Alaska Marmots and Arctic Ground Squirrels, 2008&ndash;2011</p></caption><thead><tr><th scope="col" style="text-align: center; vertical-align: bottom;">Feature</th><th scope="col" style="text-align: center; vertical-align: bottom;">Alaska marmots</th><th scope="col" style="text-align: center; vertical-align: bottom;">Arctic ground squirrels</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">torpor bouts</th><td style="text-align: center;">12</td><td style="text-align: center;">10.5</td></tr><tr><th scope="row" style="text-align: left;">duration per bout</th><td style="text-align: center;">13.81 days</td><td style="text-align: center;">16.77 days</td></tr><tr><th scope="row" style="text-align: left;">arousal episodes</th><td style="text-align: center;">11</td><td style="text-align: center;">9.5</td></tr><tr><th scope="row" style="text-align: left;">duration per episode</th><td style="text-align: center;">21.2 hours</td><td style="text-align: center;">14.2 hours</td></tr></tbody></table></figure></p>
<p>When hibernating, Alaska marmots and Arctic ground squirrels enter a state called torpor, which minimizes the energy their bodies need to function. Often a hibernating animal will temporarily come out of torpor (called an arousal episode) and its metabolic rate will rise, burning more of the precious energy the animal needs to survive the winter. Alaska marmots hibernate in groups and therefore burn less energy keeping warm during these episodes than they would if they were alone. A researcher hypothesized that because Arctic ground squirrels hibernate alone, they would likely exhibit longer bouts of torpor and shorter arousal episodes than Alaska marmots.</p>$SATQ$, $SATQ$<p>Which choice best describes data from the table that support the researcher&rsquo;s hypothesis?</p>$SATQ$, $SATQ$[{"id":"608f7f45-fb88-40e5-8e6e-19f569f725cd","content":"<p>The Alaska marmots&rsquo; arousal episodes lasted for days, while the Arctic ground squirrels&rsquo; arousal episodes lasted less than a day.</p>"},{"id":"992cca19-a2c5-4b76-ba64-6a2523a996aa","content":"<p>The Alaska marmots and the Arctic ground squirrels both maintained torpor for several consecutive days per bout, on average.</p>"},{"id":"287e31e0-12d3-49a5-a1e3-408560d2425a","content":"<p>The Alaska marmots had shorter torpor bouts and longer arousal episodes than the Arctic ground squirrels did.</p>"},{"id":"c2b21117-4a7a-4cea-89d3-ab0427f5f522","content":"<p>The Alaska marmots had more torpor bouts than arousal episodes, but their arousal episodes were much shorter than their torpor bouts.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["287e31e0-12d3-49a5-a1e3-408560d2425a"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it describes data from the table that support the researcher&rsquo;s hypothesis. According to the text, the researcher hypothesized that Arctic ground squirrels would exhibit longer torpor bouts and shorter arousal episodes than Alaska marmots do&mdash;or, put the other way, that the marmots would show shorter torpor bouts and longer arousal episodes than the ground squirrels do. The table shows data about torpor bouts and arousal episodes for the two species from 2008 to 2011. According to the table, the average duration of torpor bouts was 13.81 days for Alaska marmots, shorter than the average of 16.77 days for Arctic ground squirrels, and the average duration of arousal episodes was 21.2 hours for Alaska marmots, longer than the average of 14.2 hours for Arctic ground squirrels. Thus, the table supports the researcher&rsquo;s hypothesis by showing that Alaska marmots had shorter bouts of torpor and longer arousal episodes than Arctic ground squirrels did. </p><p>Choice A is incorrect because it inaccurately describes data from the table and doesn&rsquo;t support the researcher&rsquo;s hypothesis. The table shows that the average duration of arousal episodes was less than a day for both Alaska marmots (21.2 hours) and Arctic ground squirrels (14.2 hours). Additionally, information about arousal episodes for Alaska marmots and Arctic ground squirrels isn&rsquo;t sufficient to support a hypothesis involving comparisons of both arousal episodes and torpor bouts for those animals. Choice B is incorrect because it doesn&rsquo;t support the researcher&rsquo;s hypothesis, which involves comparisons of arousal episodes as well as torpor bouts for Alaska marmots and Arctic ground squirrels. Noting that both animals had torpor bouts lasting several days, on average, doesn&rsquo;t address arousal episodes at all, nor does it reveal how the animals&rsquo; torpor bouts compared.&nbsp;Choice D is incorrect because it doesn&rsquo;t support the researcher&rsquo;s hypothesis. Although the table does show that Alaska marmots had more torpor bouts (12) than arousal episodes (11) and that their arousal episodes were much shorter than their torpor bouts (21.2 hours and 13.81 days, respectively), comparing data across only Alaska marmot behaviors isn&rsquo;t sufficient to support a hypothesis about torpor and arousal behaviors of both Alaska marmots and Arctic ground squirrels. </p>$SATQ$, false, 0, $SATQ$OSP-516-QUA$SATQ$, $SATQ$$SATQ$, $SATQ$72cfdf75-5d1c-4213-b8a2-cf63e4a7224b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"014b3394","external_id":"e46bbf40-c607-49b6-b493-1fb84005ae31","vaultid":"8fa2cec9-59e4-4fbd-9b8f-e9cc1673026f","uId":"c65d2381-14de-4bc6-a420-f78e68dd6089","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Average Number and Duration of Torpor Bouts and Arousal Episodes for Alaska Marmots and Arctic Ground Squirrels, 2008&ndash;2011</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Feature</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Alaska marmots</th><th scope=\"col\" style=\"text-align: center; vertical-align: bottom;\">Arctic ground squirrels</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">torpor bouts</th><td style=\"text-align: center;\">12</td><td style=\"text-align: center;\">10.5</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">duration per bout</th><td style=\"text-align: center;\">13.81 days</td><td style=\"text-align: center;\">16.77 days</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">arousal episodes</th><td style=\"text-align: center;\">11</td><td style=\"text-align: center;\">9.5</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">duration per episode</th><td style=\"text-align: center;\">21.2 hours</td><td style=\"text-align: center;\">14.2 hours</td></tr></tbody></table></figure></p>\n<p>When hibernating, Alaska marmots and Arctic ground squirrels enter a state called torpor, which minimizes the energy their bodies need to function. Often a hibernating animal will temporarily come out of torpor (called an arousal episode) and its metabolic rate will rise, burning more of the precious energy the animal needs to survive the winter. Alaska marmots hibernate in groups and therefore burn less energy keeping warm during these episodes than they would if they were alone. A researcher hypothesized that because Arctic ground squirrels hibernate alone, they would likely exhibit longer bouts of torpor and shorter arousal episodes than Alaska marmots.</p>","stem":"<p>Which choice best describes data from the table that support the researcher&rsquo;s hypothesis?</p>","answerOptions":[{"id":"608f7f45-fb88-40e5-8e6e-19f569f725cd","content":"<p>The Alaska marmots&rsquo; arousal episodes lasted for days, while the Arctic ground squirrels&rsquo; arousal episodes lasted less than a day.</p>"},{"id":"992cca19-a2c5-4b76-ba64-6a2523a996aa","content":"<p>The Alaska marmots and the Arctic ground squirrels both maintained torpor for several consecutive days per bout, on average.</p>"},{"id":"287e31e0-12d3-49a5-a1e3-408560d2425a","content":"<p>The Alaska marmots had shorter torpor bouts and longer arousal episodes than the Arctic ground squirrels did.</p>"},{"id":"c2b21117-4a7a-4cea-89d3-ab0427f5f522","content":"<p>The Alaska marmots had more torpor bouts than arousal episodes, but their arousal episodes were much shorter than their torpor bouts.&nbsp;</p>"}],"keys":["287e31e0-12d3-49a5-a1e3-408560d2425a"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it describes data from the table that support the researcher&rsquo;s hypothesis. According to the text, the researcher hypothesized that Arctic ground squirrels would exhibit longer torpor bouts and shorter arousal episodes than Alaska marmots do&mdash;or, put the other way, that the marmots would show shorter torpor bouts and longer arousal episodes than the ground squirrels do. The table shows data about torpor bouts and arousal episodes for the two species from 2008 to 2011. According to the table, the average duration of torpor bouts was 13.81 days for Alaska marmots, shorter than the average of 16.77 days for Arctic ground squirrels, and the average duration of arousal episodes was 21.2 hours for Alaska marmots, longer than the average of 14.2 hours for Arctic ground squirrels. Thus, the table supports the researcher&rsquo;s hypothesis by showing that Alaska marmots had shorter bouts of torpor and longer arousal episodes than Arctic ground squirrels did. </p><p>Choice A is incorrect because it inaccurately describes data from the table and doesn&rsquo;t support the researcher&rsquo;s hypothesis. The table shows that the average duration of arousal episodes was less than a day for both Alaska marmots (21.2 hours) and Arctic ground squirrels (14.2 hours). Additionally, information about arousal episodes for Alaska marmots and Arctic ground squirrels isn&rsquo;t sufficient to support a hypothesis involving comparisons of both arousal episodes and torpor bouts for those animals. Choice B is incorrect because it doesn&rsquo;t support the researcher&rsquo;s hypothesis, which involves comparisons of arousal episodes as well as torpor bouts for Alaska marmots and Arctic ground squirrels. Noting that both animals had torpor bouts lasting several days, on average, doesn&rsquo;t address arousal episodes at all, nor does it reveal how the animals&rsquo; torpor bouts compared.&nbsp;Choice D is incorrect because it doesn&rsquo;t support the researcher&rsquo;s hypothesis. Although the table does show that Alaska marmots had more torpor bouts (12) than arousal episodes (11) and that their arousal episodes were much shorter than their torpor bouts (21.2 hours and 13.81 days, respectively), comparing data across only Alaska marmot behaviors isn&rsquo;t sufficient to support a hypothesis about torpor and arousal behaviors of both Alaska marmots and Arctic ground squirrels. </p>","parenttemplatename":"OSP-516-QUA","parenttemplateid":"","templateclusterid":"72cfdf75-5d1c-4213-b8a2-cf63e4a7224b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959337,"updateDate":1691007959337}$SATQ$::jsonb, 1691007959337, 1691007959337),
    ($SATQ$0198240a$SATQ$, $SATQ$704122ea-86c8-4130-a534-dde9ec1a52b1$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Under normal atmospheric pressure at Earth&rsquo;s surface, water molecules form a tetrahedral network stabilized by hydrogen bonds between adjacent molecules. Extreme high pressure, such as can be found in deep ocean waters, destabilizes these bonds and compresses water&rsquo;s structure, allowing water molecules within organisms to permeate proteins and impede crucial biological functions; yet deep-sea organisms known as piezophiles have adapted to extreme pressure. Studies have found a positive correlation between the depths that various piezophiles inhabit and concentrations of a compound called trimethylamine N-oxide (TMAO) in their muscle tissues, which has led a team of researchers to hypothesize that TMAO reduces water&rsquo;s compressibility.</p>$SATQ$, $SATQ$<p>Which finding, if true, would most directly support the researchers&rsquo; hypothesis?</p>$SATQ$, $SATQ$[{"id":"c446b92c-6435-4259-b26a-7151a58e637e","content":"<p>Water molecules are found to be impervious to TMAO even when the water molecules&rsquo; tetrahedral configuration has been distorted by high pressure.&nbsp;</p>"},{"id":"02397f14-70ea-43f6-96e4-6519a62984bd","content":"<p>Examination of TMAO&rsquo;s molecular structure shows that TMAO molecules retain their shape even as pressure increases.</p>"},{"id":"ce045fbd-7f23-4160-8750-ced4c9ae7052","content":"<p>A positive correlation is found between concentrations of TMAO and the rate at which water&rsquo;s molecular structure compresses as pressure increases.</p>"},{"id":"1fa1110a-0e52-429a-bfa3-3ff7a5331824","content":"<p>Analysis of water&rsquo;s molecular structure under high pressure reveals that hydrogen bonds are more stable when TMAO is present than when it is not.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["1fa1110a-0e52-429a-bfa3-3ff7a5331824"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it presents a finding that, if true, would support the researchers&rsquo; hypothesis that TMAO reduces water&rsquo;s compressibility. The text explains that at great depths in the ocean, extreme pressure compresses the molecular structure of water by destabilizing the hydrogen bonds between adjacent molecules, thereby allowing water to penetrate proteins and harm the associated organisms. However, deep-sea organisms called piezophiles have adapted to live at these depths and previous studies show a positive correlation between the depth at which a piezophile species lives and the species&rsquo; level of the compound TMAO. Because this hypothesis links TMAO levels with reduced compressibility of water&rsquo;s tetrahedral molecular structure, a finding that TMAO helps maintain the hydrogen bonds between water molecules under high pressure would strongly support that hypothesis.</p><p>Choice A is incorrect. Although the researchers&rsquo; hypothesis suggests a relationship between TMAO and water molecules&rsquo; tetrahedral molecular structure, that relationship involves TMAO helping maintain water&rsquo;s tetrahedral molecular structure under high pressure; as presented in the text, the hypothesis doesn&rsquo;t contend that water molecules are impervious to, or incapable of being penetrated by, TMAO. Choice B is incorrect because the text discusses how the molecular structure of water, not TMAO, is compressed under extreme pressure and never addresses how TMAO might be affected by such pressure. Choice C is incorrect because the researchers&rsquo; hypothesis holds that water under extreme pressure is more resistant, not less, to being compressed when TMAO concentrations are higher. Moreover, the positive correlation mentioned in the text is between TMAO concentrations and the depths at which piezophiles live, not between concentrations of TMAO and the rate at which water&rsquo;s molecular structure compresses as pressure increases.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"0198240a","external_id":"704122ea-86c8-4130-a534-dde9ec1a52b1","vaultid":null,"uId":"73c5b7e6-297f-4d02-a9f7-3650267e42f6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Under normal atmospheric pressure at Earth&rsquo;s surface, water molecules form a tetrahedral network stabilized by hydrogen bonds between adjacent molecules. Extreme high pressure, such as can be found in deep ocean waters, destabilizes these bonds and compresses water&rsquo;s structure, allowing water molecules within organisms to permeate proteins and impede crucial biological functions; yet deep-sea organisms known as piezophiles have adapted to extreme pressure. Studies have found a positive correlation between the depths that various piezophiles inhabit and concentrations of a compound called trimethylamine N-oxide (TMAO) in their muscle tissues, which has led a team of researchers to hypothesize that TMAO reduces water&rsquo;s compressibility.</p>","stem":"<p>Which finding, if true, would most directly support the researchers&rsquo; hypothesis?</p>","answerOptions":[{"id":"c446b92c-6435-4259-b26a-7151a58e637e","content":"<p>Water molecules are found to be impervious to TMAO even when the water molecules&rsquo; tetrahedral configuration has been distorted by high pressure.&nbsp;</p>"},{"id":"02397f14-70ea-43f6-96e4-6519a62984bd","content":"<p>Examination of TMAO&rsquo;s molecular structure shows that TMAO molecules retain their shape even as pressure increases.</p>"},{"id":"ce045fbd-7f23-4160-8750-ced4c9ae7052","content":"<p>A positive correlation is found between concentrations of TMAO and the rate at which water&rsquo;s molecular structure compresses as pressure increases.</p>"},{"id":"1fa1110a-0e52-429a-bfa3-3ff7a5331824","content":"<p>Analysis of water&rsquo;s molecular structure under high pressure reveals that hydrogen bonds are more stable when TMAO is present than when it is not.</p>"}],"keys":["1fa1110a-0e52-429a-bfa3-3ff7a5331824"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it presents a finding that, if true, would support the researchers&rsquo; hypothesis that TMAO reduces water&rsquo;s compressibility. The text explains that at great depths in the ocean, extreme pressure compresses the molecular structure of water by destabilizing the hydrogen bonds between adjacent molecules, thereby allowing water to penetrate proteins and harm the associated organisms. However, deep-sea organisms called piezophiles have adapted to live at these depths and previous studies show a positive correlation between the depth at which a piezophile species lives and the species&rsquo; level of the compound TMAO. Because this hypothesis links TMAO levels with reduced compressibility of water&rsquo;s tetrahedral molecular structure, a finding that TMAO helps maintain the hydrogen bonds between water molecules under high pressure would strongly support that hypothesis.</p><p>Choice A is incorrect. Although the researchers&rsquo; hypothesis suggests a relationship between TMAO and water molecules&rsquo; tetrahedral molecular structure, that relationship involves TMAO helping maintain water&rsquo;s tetrahedral molecular structure under high pressure; as presented in the text, the hypothesis doesn&rsquo;t contend that water molecules are impervious to, or incapable of being penetrated by, TMAO. Choice B is incorrect because the text discusses how the molecular structure of water, not TMAO, is compressed under extreme pressure and never addresses how TMAO might be affected by such pressure. Choice C is incorrect because the researchers&rsquo; hypothesis holds that water under extreme pressure is more resistant, not less, to being compressed when TMAO concentrations are higher. Moreover, the positive correlation mentioned in the text is between TMAO concentrations and the depths at which piezophiles live, not between concentrations of TMAO and the rate at which water&rsquo;s molecular structure compresses as pressure increases.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323045,"updateDate":1730147323045}$SATQ$::jsonb, 1730147323045, 1730147323045),
    ($SATQ$01989d77$SATQ$, $SATQ$6b5f6281-c186-4b8e-b5b1-e480cda187ec$SATQ$::uuid, $SATQ$3abb7e5a-9322-4f13-8da7-b3b5783a6ade$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$INF$SATQ$, $SATQ$Inferences$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Microbes that live in shallow lakes and ponds produce methane, a harmful greenhouse gas. Ecologist Ralf Aben and his team wanted to see how different types of shallow-water plants might affect the amount of methane that escapes into the atmosphere. Aben&rsquo;s team set up some water tanks with soil and microbes from local ponds. Some tanks had a type of underwater plant that grows in the soil called watermilfoil. Other tanks had either duckweed, a type of plant that floats on the water&rsquo;s surface, or algae. Aben and his team found that tanks with duckweed and algae released higher levels of methane than tanks with watermilfoil did. This finding suggests that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most logically completes the text?</p>$SATQ$, $SATQ$[{"id":"c8a7dcb3-5661-4742-bb6b-2eb2d13d92ed","content":"<p>the presence of some kinds of underwater plants like watermilfoil helps prevent methane from escaping shallow lakes and ponds.</p>"},{"id":"e2988ccd-8cc5-4281-bd78-d246c9fda1d5","content":"<p>shallow lakes and ponds release more methane than deeper bodies of water because shallow bodies of water usually have more plants than deep bodies of water do. &nbsp;&nbsp;&nbsp;</p>"},{"id":"5a49c5a7-22ef-4d4f-9342-33d7641e1f06","content":"<p>shallow lakes and ponds are more likely to contain algae than to contain either watermilfoil or duckweed.</p>"},{"id":"871c1cb5-7798-4f53-948b-b8da2029dfb7","content":"<p>having a mix of algae, underwater plants, and floating plants is the best way to reduce the amount of methane in shallow lakes and ponds.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["c8a7dcb3-5661-4742-bb6b-2eb2d13d92ed"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The passage tells us that &ldquo;tanks with duckweed (a floating plant) and algae released higher levels of methane than tanks with watermilfoil (an underwater plant) did.&rdquo; This suggests that the presence of some kinds of underwater plants like watermilfoil may help prevent methane from escaping shallow lakes and ponds. </p><p>Choice B is incorrect. The passage doesn&rsquo;t mention deeper bodies of water at all, so there&rsquo;s no basis for this inference. Choice C is incorrect. The passage doesn&rsquo;t compare the likelihood of shallow lakes and ponds containing algae, watermilfoil, or duckweed. Choice D is incorrect. The study didn&rsquo;t include any tanks with a mix of plants, so there&rsquo;s no basis for this inference. </p>$SATQ$, false, 0, $SATQ$OSP-KA-INF-E009$SATQ$, $SATQ$$SATQ$, $SATQ$936a1c6a-8e5c-4c31-90b4-d7c42721c9a0$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"01989d77","external_id":"6b5f6281-c186-4b8e-b5b1-e480cda187ec","vaultid":"3abb7e5a-9322-4f13-8da7-b3b5783a6ade","uId":"2356fb12-daed-44b1-bce4-110b7e6b237a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"INF","skill_desc":"Inferences","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Microbes that live in shallow lakes and ponds produce methane, a harmful greenhouse gas. Ecologist Ralf Aben and his team wanted to see how different types of shallow-water plants might affect the amount of methane that escapes into the atmosphere. Aben&rsquo;s team set up some water tanks with soil and microbes from local ponds. Some tanks had a type of underwater plant that grows in the soil called watermilfoil. Other tanks had either duckweed, a type of plant that floats on the water&rsquo;s surface, or algae. Aben and his team found that tanks with duckweed and algae released higher levels of methane than tanks with watermilfoil did. This finding suggests that <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice most logically completes the text?</p>","answerOptions":[{"id":"c8a7dcb3-5661-4742-bb6b-2eb2d13d92ed","content":"<p>the presence of some kinds of underwater plants like watermilfoil helps prevent methane from escaping shallow lakes and ponds.</p>"},{"id":"e2988ccd-8cc5-4281-bd78-d246c9fda1d5","content":"<p>shallow lakes and ponds release more methane than deeper bodies of water because shallow bodies of water usually have more plants than deep bodies of water do. &nbsp;&nbsp;&nbsp;</p>"},{"id":"5a49c5a7-22ef-4d4f-9342-33d7641e1f06","content":"<p>shallow lakes and ponds are more likely to contain algae than to contain either watermilfoil or duckweed.</p>"},{"id":"871c1cb5-7798-4f53-948b-b8da2029dfb7","content":"<p>having a mix of algae, underwater plants, and floating plants is the best way to reduce the amount of methane in shallow lakes and ponds.&nbsp;</p>"}],"keys":["c8a7dcb3-5661-4742-bb6b-2eb2d13d92ed"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The passage tells us that &ldquo;tanks with duckweed (a floating plant) and algae released higher levels of methane than tanks with watermilfoil (an underwater plant) did.&rdquo; This suggests that the presence of some kinds of underwater plants like watermilfoil may help prevent methane from escaping shallow lakes and ponds. </p><p>Choice B is incorrect. The passage doesn&rsquo;t mention deeper bodies of water at all, so there&rsquo;s no basis for this inference. Choice C is incorrect. The passage doesn&rsquo;t compare the likelihood of shallow lakes and ponds containing algae, watermilfoil, or duckweed. Choice D is incorrect. The study didn&rsquo;t include any tanks with a mix of plants, so there&rsquo;s no basis for this inference. </p>","parenttemplatename":"OSP-KA-INF-E009","parenttemplateid":"","templateclusterid":"936a1c6a-8e5c-4c31-90b4-d7c42721c9a0","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959368,"updateDate":1691007959368}$SATQ$::jsonb, 1691007959368, 1691007959368),
    ($SATQ$01c1d9ee$SATQ$, $SATQ$15eb5d10-e935-4161-bec5-d9798b5f47e3$SATQ$::uuid, $SATQ$178c6d02-3637-498d-ace3-0029c5c6d40e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p><figure class="table"><table class="gdr"><caption style="caption-side: top;"><p style="text-align: center;">Swahili Speakers in Three African Countries</p></caption><thead><tr><th scope="col" style="text-align: center;vertical-align: bottom;">Country</th><th scope="col" style="text-align: center;vertical-align: bottom;">Approximate number of speakers (in millions)</th><th scope="col" style="text-align: center;vertical-align: bottom;">Estimated % of population</th></tr></thead><tbody><tr><th scope="row" style="text-align: left;">Democratic Republic of the Congo</th><td style="text-align: center;">22</td><td style="text-align: center;">25</td></tr><tr><th scope="row" style="text-align: left;">Kenya</th><td style="text-align: center;">55</td><td style="text-align: center;">100</td></tr><tr><th scope="row" style="text-align: left;">Tanzania</th><td style="text-align: center;">61</td><td style="text-align: center;">100</td></tr></tbody></table></figure></p>
<p>Swahili is estimated to be the first language of up to 15 million people worldwide. It&rsquo;s also an officially recognized language in Tanzania, Kenya, and the Democratic Republic of the Congo, which means these countries use Swahili in government documents and proceedings. <span role="region" aria-label="Referenced Content"><u>But even in countries where almost everyone speaks Swahili, for many it isn&rsquo;t their first language but is instead their second, third, or even fourth language.</u></span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the table to support the underlined claim?</p>$SATQ$, $SATQ$[{"id":"f06e2141-334e-45fc-acf4-f6cf73ae1e06","content":"<p>Tanzania has approximately 61 million Swahili speakers, which is much more than the estimated total number of people worldwide for whom Swahili is their first language.</p>"},{"id":"3571b88f-0ede-4e7e-9581-3ef18a4d0222","content":"<p>Tanzania is estimated to have at most 15 million Swahili speakers, while the country&rsquo;s total population is approximately 61 million people.</p>"},{"id":"bb88ede0-5458-44a8-9af5-9b9e03f69f65","content":"<p>Approximately 100 percent of the people who speak Swahili as their first language live in Kenya, which has a total population of approximately 55 million people.</p>"},{"id":"33b83177-937d-4160-8dcb-bc8a58120c43","content":"<p>Approximately 100 percent of Kenya&rsquo;s population speaks Swahili, while only about 25 percent of the Democratic Republic of the Congo&rsquo;s population speaks Swahili.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["f06e2141-334e-45fc-acf4-f6cf73ae1e06"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most effectively uses data from the table to support the underlined claim. The text indicates that Swahili is the first language of up to 15 million people worldwide. The text goes on to claim, in the underlined portion, that even in countries where nearly everyone speaks Swahili, many of the language&rsquo;s speakers don&rsquo;t have Swahili as their first language. The table indicates that 61 million people in Tanzania, which amounts to 100 percent of the population, speak Swahili. If 61 million people in Tanzania speak Swahili, but only 15 million people worldwide have Swahili as their first language, that means there are many people in Tanzania who speak Swahili as a language other than their first language. This information about Swahili speakers in Tanzania therefore supports the claim that many Swahili speakers in countries where nearly everyone speaks Swahili speak it as a language other than their first language (such as their second, third, or fourth language).&nbsp;</p><p>Choice B is incorrect because it doesn&rsquo;t accurately describe information in the table. According to the table, Tanzania has 61 million Swahili speakers, not at most 15 million Swahili speakers. Additionally, the table indicates that 100 percent of Tanzania&rsquo;s population speak Swahili, which means that the number of Swahili speakers in the country and the country&rsquo;s total population should be the same, not that they should differ by such a large amount. Choice C is incorrect because there&rsquo;s no information in the table or the text that indicates where people who speak Swahili as their first language live. Although Kenya&rsquo;s total population can be inferred from the table&mdash;if Kenya has 55 million Swahili speakers and 100% of Kenya&rsquo;s population speak Swahili, then Kenya must have a population of 55 million people&mdash;nothing suggests that all the people who speak Swahili as their first language live in a single country, let alone that they all live in Kenya.&nbsp;Choice D is incorrect. Although the table does indicate that 100 percent of Kenya&rsquo;s population and 25 percent of the Democratic Republic of the Congo&rsquo;s population speak Swahili, this comparison is irrelevant to the claim that Swahili isn&rsquo;t the first language of many of its speakers even in countries where almost everyone speaks Swahili. On its own, a difference in the proportions of the population who speak Swahili cannot reveal whether those Swahili speakers have Swahili as their first language or a subsequent language.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-541-QUA$SATQ$, $SATQ$$SATQ$, $SATQ$0180544d-d259-4a2d-bed8-e59cec7caa55$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"01c1d9ee","external_id":"15eb5d10-e935-4161-bec5-d9798b5f47e3","vaultid":"178c6d02-3637-498d-ace3-0029c5c6d40e","uId":"ad981f6b-3380-41b2-a2dc-cc0911b04df2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p><figure class=\"table\"><table class=\"gdr\"><caption style=\"caption-side: top;\"><p style=\"text-align: center;\">Swahili Speakers in Three African Countries</p></caption><thead><tr><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Country</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Approximate number of speakers (in millions)</th><th scope=\"col\" style=\"text-align: center;vertical-align: bottom;\">Estimated % of population</th></tr></thead><tbody><tr><th scope=\"row\" style=\"text-align: left;\">Democratic Republic of the Congo</th><td style=\"text-align: center;\">22</td><td style=\"text-align: center;\">25</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Kenya</th><td style=\"text-align: center;\">55</td><td style=\"text-align: center;\">100</td></tr><tr><th scope=\"row\" style=\"text-align: left;\">Tanzania</th><td style=\"text-align: center;\">61</td><td style=\"text-align: center;\">100</td></tr></tbody></table></figure></p>\n<p>Swahili is estimated to be the first language of up to 15 million people worldwide. It&rsquo;s also an officially recognized language in Tanzania, Kenya, and the Democratic Republic of the Congo, which means these countries use Swahili in government documents and proceedings. <span role=\"region\" aria-label=\"Referenced Content\"><u>But even in countries where almost everyone speaks Swahili, for many it isn&rsquo;t their first language but is instead their second, third, or even fourth language.</u></span></p>","stem":"<p>Which choice most effectively uses data from the table to support the underlined claim?</p>","answerOptions":[{"id":"f06e2141-334e-45fc-acf4-f6cf73ae1e06","content":"<p>Tanzania has approximately 61 million Swahili speakers, which is much more than the estimated total number of people worldwide for whom Swahili is their first language.</p>"},{"id":"3571b88f-0ede-4e7e-9581-3ef18a4d0222","content":"<p>Tanzania is estimated to have at most 15 million Swahili speakers, while the country&rsquo;s total population is approximately 61 million people.</p>"},{"id":"bb88ede0-5458-44a8-9af5-9b9e03f69f65","content":"<p>Approximately 100 percent of the people who speak Swahili as their first language live in Kenya, which has a total population of approximately 55 million people.</p>"},{"id":"33b83177-937d-4160-8dcb-bc8a58120c43","content":"<p>Approximately 100 percent of Kenya&rsquo;s population speaks Swahili, while only about 25 percent of the Democratic Republic of the Congo&rsquo;s population speaks Swahili.</p>"}],"keys":["f06e2141-334e-45fc-acf4-f6cf73ae1e06"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most effectively uses data from the table to support the underlined claim. The text indicates that Swahili is the first language of up to 15 million people worldwide. The text goes on to claim, in the underlined portion, that even in countries where nearly everyone speaks Swahili, many of the language&rsquo;s speakers don&rsquo;t have Swahili as their first language. The table indicates that 61 million people in Tanzania, which amounts to 100 percent of the population, speak Swahili. If 61 million people in Tanzania speak Swahili, but only 15 million people worldwide have Swahili as their first language, that means there are many people in Tanzania who speak Swahili as a language other than their first language. This information about Swahili speakers in Tanzania therefore supports the claim that many Swahili speakers in countries where nearly everyone speaks Swahili speak it as a language other than their first language (such as their second, third, or fourth language).&nbsp;</p><p>Choice B is incorrect because it doesn&rsquo;t accurately describe information in the table. According to the table, Tanzania has 61 million Swahili speakers, not at most 15 million Swahili speakers. Additionally, the table indicates that 100 percent of Tanzania&rsquo;s population speak Swahili, which means that the number of Swahili speakers in the country and the country&rsquo;s total population should be the same, not that they should differ by such a large amount. Choice C is incorrect because there&rsquo;s no information in the table or the text that indicates where people who speak Swahili as their first language live. Although Kenya&rsquo;s total population can be inferred from the table&mdash;if Kenya has 55 million Swahili speakers and 100% of Kenya&rsquo;s population speak Swahili, then Kenya must have a population of 55 million people&mdash;nothing suggests that all the people who speak Swahili as their first language live in a single country, let alone that they all live in Kenya.&nbsp;Choice D is incorrect. Although the table does indicate that 100 percent of Kenya&rsquo;s population and 25 percent of the Democratic Republic of the Congo&rsquo;s population speak Swahili, this comparison is irrelevant to the claim that Swahili isn&rsquo;t the first language of many of its speakers even in countries where almost everyone speaks Swahili. On its own, a difference in the proportions of the population who speak Swahili cannot reveal whether those Swahili speakers have Swahili as their first language or a subsequent language.&nbsp;</p>","parenttemplatename":"OSP-541-QUA","parenttemplateid":"","templateclusterid":"0180544d-d259-4a2d-bed8-e59cec7caa55","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959338,"updateDate":1691007959338}$SATQ$::jsonb, 1691007959338, 1691007959338),
    ($SATQ$0240d11c$SATQ$, $SATQ$05b51061-19d4-45fe-8086-a6b565cc8902$SATQ$::uuid, $SATQ$df61958c-9aed-4249-89d9-52f6e33b209c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In the twentieth century, ethnographers made a concerted effort to collect Mexican American folklore, but they did not always agree about that folklore&rsquo;s origins. Scholars such as Aurelio Espinosa claimed that Mexican American folklore derived largely from the folklore of Spain, which ruled Mexico and what is now the southwestern United States from the sixteenth to early nineteenth centuries. Scholars such as Am&eacute;rico Paredes, by contrast, argued that while some Spanish influence is undeniable, Mexican American folklore is mainly the product of the ongoing interactions of various cultures in Mexico and the United States. </p>$SATQ$, $SATQ$<p>Which finding, if true, would most directly support Paredes&rsquo;s argument?</p>$SATQ$, $SATQ$[{"id":"65430d14-ecde-4f68-aed6-8995fdee8134","content":"<p>The folklore that the ethnographers collected included several songs written in the form of a <span lang=\"es\"><em>d&eacute;cima</em></span>, a type of poem originating in late sixteenth-century Spain.&nbsp;</p>"},{"id":"3464264d-63d4-4e1d-9725-fa41db89dd48","content":"<p>Much of the folklore that the ethnographers collected had similar elements from region to region.&nbsp;</p>"},{"id":"f3a30c36-9d35-4569-ae70-8dc2a44aac33","content":"<p>Most of the folklore that the ethnographers collected was previously unknown to scholars.&nbsp;</p>"},{"id":"a4e48ae2-c996-4464-be93-3beea692748b","content":"<p>Most of the folklore that the ethnographers collected consisted of <span lang=\"es\"><em>corridos</em></span>&mdash;ballads about history and social life&mdash;of a clearly recent origin.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["a4e48ae2-c996-4464-be93-3beea692748b"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it presents a finding that, if true, would support Paredes&rsquo;s argument that Mexican-American folklore is mostly the result of cultural interactions in Mexico and the United States rather than an adaptation of Spanish folklore. The text describes a disagreement among scholars about whether Mexican-American folklore mostly derived from the folklore of Spain or originated in Mexico and the United States as cultures there have interacted. The latter view is the argument that Paredes puts forward. If Mexican-American folklore collected in the twentieth century mostly consists of ballads about history and social life that originated recently, then that would support Paredes&rsquo;s argument, since it would suggest that the folklore mostly arose after Spanish rule ended in the early nineteenth century and that the folklore reflects cultural interactions in Mexico and the United States rather than traditions from Spain.&nbsp;</p><p>Choice A is incorrect because the inclusion of songs influenced by sixteenth-century Spanish poetry among Mexican-American folklore collected in the twentieth century would not support Paredes&rsquo;s view that the folklore was the result of cultural interactions in Mexico and the United States rather than an offshoot of Spanish folklore. If anything, the presence of such songs among the folklore collected in the twentieth century would weaken Paredes&rsquo;s argument, since it would reflect the influence of Spanish culture on the folklore.&nbsp;Choice B is incorrect because the mere presence of similarities in Mexican-American folklore across regions would not be sufficient to draw a conclusion about where the folklore originated, let alone to support Paredes&rsquo;s argument that the folklore reflects cultural interactions in Mexico and the United States. In fact, since Paredes argued that Mexican-American folklore is the product of various cultures interacting in Mexico and the United States, he would likely expect there to be regional variations in folklore as different cultures have interacted in different places.&nbsp;Choice C is incorrect because scholars&rsquo; previous ignorance of the folklore would have no bearing on Paredes&rsquo;s argument that Mexican-American folklore mostly reflects cultural interactions in Mexico and the United States. The folklore&rsquo;s origins are independent of scholars&rsquo; knowledge of the folklore.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-303-TXT$SATQ$, $SATQ$$SATQ$, $SATQ$d5cb784f-9135-4d63-a6b9-999aae6610ac$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"0240d11c","external_id":"05b51061-19d4-45fe-8086-a6b565cc8902","vaultid":"df61958c-9aed-4249-89d9-52f6e33b209c","uId":"757fe2e5-4e7a-4fc3-a15c-31dc0d249261","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>In the twentieth century, ethnographers made a concerted effort to collect Mexican American folklore, but they did not always agree about that folklore&rsquo;s origins. Scholars such as Aurelio Espinosa claimed that Mexican American folklore derived largely from the folklore of Spain, which ruled Mexico and what is now the southwestern United States from the sixteenth to early nineteenth centuries. Scholars such as Am&eacute;rico Paredes, by contrast, argued that while some Spanish influence is undeniable, Mexican American folklore is mainly the product of the ongoing interactions of various cultures in Mexico and the United States. </p>","stem":"<p>Which finding, if true, would most directly support Paredes&rsquo;s argument?</p>","answerOptions":[{"id":"65430d14-ecde-4f68-aed6-8995fdee8134","content":"<p>The folklore that the ethnographers collected included several songs written in the form of a <span lang=\"es\"><em>d&eacute;cima</em></span>, a type of poem originating in late sixteenth-century Spain.&nbsp;</p>"},{"id":"3464264d-63d4-4e1d-9725-fa41db89dd48","content":"<p>Much of the folklore that the ethnographers collected had similar elements from region to region.&nbsp;</p>"},{"id":"f3a30c36-9d35-4569-ae70-8dc2a44aac33","content":"<p>Most of the folklore that the ethnographers collected was previously unknown to scholars.&nbsp;</p>"},{"id":"a4e48ae2-c996-4464-be93-3beea692748b","content":"<p>Most of the folklore that the ethnographers collected consisted of <span lang=\"es\"><em>corridos</em></span>&mdash;ballads about history and social life&mdash;of a clearly recent origin.&nbsp;</p>"}],"keys":["a4e48ae2-c996-4464-be93-3beea692748b"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it presents a finding that, if true, would support Paredes&rsquo;s argument that Mexican-American folklore is mostly the result of cultural interactions in Mexico and the United States rather than an adaptation of Spanish folklore. The text describes a disagreement among scholars about whether Mexican-American folklore mostly derived from the folklore of Spain or originated in Mexico and the United States as cultures there have interacted. The latter view is the argument that Paredes puts forward. If Mexican-American folklore collected in the twentieth century mostly consists of ballads about history and social life that originated recently, then that would support Paredes&rsquo;s argument, since it would suggest that the folklore mostly arose after Spanish rule ended in the early nineteenth century and that the folklore reflects cultural interactions in Mexico and the United States rather than traditions from Spain.&nbsp;</p><p>Choice A is incorrect because the inclusion of songs influenced by sixteenth-century Spanish poetry among Mexican-American folklore collected in the twentieth century would not support Paredes&rsquo;s view that the folklore was the result of cultural interactions in Mexico and the United States rather than an offshoot of Spanish folklore. If anything, the presence of such songs among the folklore collected in the twentieth century would weaken Paredes&rsquo;s argument, since it would reflect the influence of Spanish culture on the folklore.&nbsp;Choice B is incorrect because the mere presence of similarities in Mexican-American folklore across regions would not be sufficient to draw a conclusion about where the folklore originated, let alone to support Paredes&rsquo;s argument that the folklore reflects cultural interactions in Mexico and the United States. In fact, since Paredes argued that Mexican-American folklore is the product of various cultures interacting in Mexico and the United States, he would likely expect there to be regional variations in folklore as different cultures have interacted in different places.&nbsp;Choice C is incorrect because scholars&rsquo; previous ignorance of the folklore would have no bearing on Paredes&rsquo;s argument that Mexican-American folklore mostly reflects cultural interactions in Mexico and the United States. The folklore&rsquo;s origins are independent of scholars&rsquo; knowledge of the folklore.&nbsp;</p>","parenttemplatename":"OSP-303-TXT","parenttemplateid":"","templateclusterid":"d5cb784f-9135-4d63-a6b9-999aae6610ac","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959334,"updateDate":1691007959334}$SATQ$::jsonb, 1691007959334, 1691007959334),
    ($SATQ$02848335$SATQ$, $SATQ$74e5885a-cf6e-4b0a-b09a-04d8579c9935$SATQ$::uuid, $SATQ$5b9ae204-876c-4943-84c5-380e02e06e02$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Information and Ideas$SATQ$, $SATQ$INI$SATQ$, $SATQ$COE$SATQ$, $SATQ$Command of Evidence$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<figure class="image"><svg aria-label="Bar graph titled Power Conversion Efficiency of Lowest and Highest Performing Spin-coated and Spray-coated Electron Transport Layers. The horizontal axis is labeled Thickness. 2 data categories are shown. The vertical axis is labeled Power conversion efficiency, in percent. It ranges from 0 to 18 in increments of 2. Refer to long description." height="525.3912963867188" role="img" viewbox="0 0 380 525.3912963867188" width="380" xmlns="http://www.w3.org/2000/svg"><g data-name="Layer 1" id="ed420550-79eb-48d4-af01-cd27cdd08afd"><defs>
