org/2000/svg" x1="76.703125" y1="325.16666666666663" x2="385" y2="325.16666666666663" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="70.703125" y1="325.16666666666663" x2="82.703125" y2="325.16666666666663" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(64.703125 331.16666666666663)" fill="#000000" font-size="19.84" font-family="Crimson Text">1</text><line xmlns="http://www.w3.org/2000/svg" x1="76.703125" y1="346" x2="385" y2="346" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><line xmlns="http://www.w3.org/2000/svg" x1="70.703125" y1="346" x2="82.703125" y2="346" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text text-anchor="end" transform="translate(64.703125 352)" fill="#000000" font-size="19.84" font-family="Crimson Text">0</text><text text-anchor="middle" transform="translate(24 221) rotate(-90)" fill="#000000" font-size="19.84" font-family="Crimson Text">Time (days)</text><line xmlns="http://www.w3.org/2000/svg" x1="76.703125" y1="96" x2="76.703125" y2="346" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="100.41826923076923" y="179.33333333333334" height="166.66666666666666" width="23.71514423076923" fill="#B3B3B3" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="124.13341346153845" y="116.83333333333334" height="229.16666666666666" width="23.71514423076923" fill="#333333" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><text xmlns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="end" transform="translate(134.05341346153844 365.84) rotate(-40)" fill="#000000" font-size="19.84" font-family="Crimson Text">14&deg;C</text><rect xmlns="http://www.w3.org/2000/svg" x="171.5637019230769" y="221" height="125" width="23.71514423076923" fill="#B3B3B3" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="195.27884615384613" y="148.08333333333334" height="197.91666666666666" width="23.71514423076923" fill="#333333" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><text xmlns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="end" transform="translate(205.19884615384612 365.84) rotate(-40)" fill="#000000" font-size="19.84" font-family="Crimson Text">16&deg;C</text><rect xmlns="http://www.w3.org/2000/svg" x="242.70913461538458" y="231.41666666666669" height="114.58333333333333" width="23.71514423076923" fill="#B3B3B3" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="266.4242788461538" y="168.91666666666669" height="177.08333333333331" width="23.71514423076923" fill="#333333" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><text xmlns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="end" transform="translate(276.3442788461538 365.84) rotate(-40)" fill="#000000" font-size="19.84" font-family="Crimson Text">18&deg;C</text><rect xmlns="http://www.w3.org/2000/svg" x="313.85456730769226" y="262.6666666666667" height="83.33333333333333" width="23.71514423076923" fill="#B3B3B3" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="337.5697115384615" y="231.41666666666669" height="114.58333333333333" width="23.71514423076923" fill="#333333" stroke="#000000" stroke-linecap="round" stroke-linejoin="mitre" stroke-width="0.9"/><text xmlns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="end" transform="translate(347.4897115384615 365.84) rotate(-40)" fill="#000000" font-size="19.84" font-family="Crimson Text">20&deg;C</text><text text-anchor="middle" transform="translate(230.8515625 24)" fill="#000000" font-size="19.84" font-family="Crimson Text">Banana Ripening Time at Different </text><text text-anchor="middle" transform="translate(230.8515625 48)" fill="#000000" font-size="19.84" font-family="Crimson Text">Temperatures with and without </text><text text-anchor="middle" transform="translate(230.8515625 72)" fill="#000000" font-size="19.84" font-family="Crimson Text">Ethylene Treatment</text><text text-anchor="middle" transform="translate(230.8515625 423.469150390625)" fill="#000000" font-size="19.84" font-family="Crimson Text">Temperature (degrees Celsius)</text><rect xmlns="http://www.w3.org/2000/svg" fill="none" x="116.31851959228516" y="440.629150390625" height="26.84" width="229.0660858154297" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9"/><rect xmlns="http://www.w3.org/2000/svg" x="123.31851959228516" y="447.629150390625" height="12" width="12" fill="#B3B3B3" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9"/><text transform="translate(142.31851959228516 459.629150390625)" text-anchor="top" fill="#000000" font-size="19.84" font-family="Crimson Text">ethylene</text><rect xmlns="http://www.w3.org/2000/svg" x="221.93219757080078" y="447.629150390625" height="12" width="12" fill="#333333" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9"/><text transform="translate(240.93219757080078 459.629150390625)" text-anchor="top" fill="#000000" font-size="19.84" font-family="Crimson Text">no ethylene</text></g></svg></figure><div class="sr-only" role="region" aria-label="Long description for bar graph titled Banana Ripening Time at Different Temperatures with and without Ethylene Treatment"><ul>
<li>For each data category, the following bars are shown:<br/>
<ul>
<li>ethylene</li>
<li>no ethylene</li>
</ul>
</li>
<li>All data are approximate.</li>
<li>The Time data for the 4 categories are as follows:<br/>
<ul>
<li>14 degrees Celsius:<br/>
<ul>
<li>ethylene: 8 days</li>
<li>no ethylene: 11 days</li>
</ul>
</li>
<li>16 degrees Celsius:<br/>
<ul>
<li>ethylene: 6 days</li>
<li>no ethylene: 9.5 days</li>
</ul>
</li>
<li>18 degrees Celsius:<br/>
<ul>
<li>ethylene: 5.5 days</li>
<li>no ethylene: 8.5 days</li>
</ul>
</li>
<li>20 degrees Celsius:<br/>
<ul>
<li>ethylene: 4 days</li>
<li>no ethylene: 5.5 days</li>
</ul>
</li>
</ul>
</li>
</ul></div>
<p>A student is conducting an experiment to test the effect of temperature and ethylene treatment on the ripening speed of bananas. The student treated some bananas with ethylene while leaving others untreated, then allowed both types of bananas to ripen at one of four different temperatures. Comparing the data for bananas with and without ethylene, the student concluded that <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice most effectively uses data from the graph to complete the student&rsquo;s conclusion?</p>$SATQ$, $SATQ$[{"id":"7a90092c-024f-4d77-a615-ed3ee1cd74ac","content":"<p>20&deg;C is the ideal temperature at which to store bananas to slow ripening time.&nbsp;</p>"},{"id":"ba9e0108-1bb5-4365-b96f-6672003203e8","content":"<p>for those bananas that were not treated with ethylene, differences in temperature were not associated with absolute differences in ripening time.</p>"},{"id":"56aee830-7d3b-41a3-812e-c44fd9cc6d9f","content":"<p>bananas treated with ethylene ripen faster at 14&deg;C and 16&deg;C than at 18&deg;C and 20&deg;C.</p>"},{"id":"c2c55a14-b682-405c-9f78-0d7d7e55b146","content":"<p>ethylene was associated with a greater absolute change in ripening time at 14&deg;C, 16&deg;C, and 18&deg;C than at 20&deg;C.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["c2c55a14-b682-405c-9f78-0d7d7e55b146"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most effectively uses data from the graph to complete the student&rsquo;s conclusion about banana ripening time with and without ethylene at different temperatures. The graph shows that at 20&deg;C, the gap between the two bars showing ripening times for ethylene-treated bananas and untreated bananas crosses fewer than 2 gridlines (from about 4 days for ethylene-treated bananas to about 5.5 days for untreated bananas). Meanwhile, the graph shows that at 14&deg;C, 16&deg;C, and 18&deg;C, the gap between the bars crosses more than 2 gridlines (from about 8 days for treated bananas to about 11 days for untreated bananas at 14&deg;C; from about 6 days for treated bananas to about 9.5 days for untreated bananas at 16&deg;C; and from about 5.5 days for treated bananas to about 8.5 days for untreated bananas at 18&deg;C). Since the gap between the bars at each of these temperatures crosses more than 2 gridlines, and since each of these gaps is larger than the gap between the bars at 20&deg;C, it can be concluded that ethylene was associated with a greater absolute change in ripening time at 14&deg;C, 16&deg;C, and 18&deg;C  than at 20&deg;C.</p><p>Choice A is incorrect because the graph shows that ethylene-treated bananas stored at 20&deg;C ripen more quickly than ethylene-treated bananas stored at the other temperatures do (about 4 days at 20&deg;C vs. about 5.5, 6, and 8 days at 18&deg;C, 16&deg;C, and 14&deg;C, respectively) and that untreated bananas stored at 20&deg;C ripen more quickly than untreated bananas stored at the other temperatures do (about 5.5 days at 20&deg;C vs. about 8.5, 9.5, and 11 days at 18&deg;C, 16&deg;C, and 14&deg;C, respectively). The information in the graph therefore indicates that storing bananas at 20&deg;C speeds up ripening time relative to storing bananas at the other temperatures shown, not that this storage temperature slows ripening time. Choice B is incorrect because the graph shows that as temperature increases, the ripening time of untreated bananas decreases, from about 11 days at 14&deg;C to about 5.5 days at 20&deg;C, with no exceptions to this trend. The graph therefore shows that differences in temperature were associated with absolute differences in ripening time, not that there was no association between differences in temperature and differences in ripening time. Choice C is incorrect because the graph shows that ripening times of ethylene-treated bananas at 14&deg;C and 16&deg;C were about 8 and 6 days, respectively, which is greater than, not less than, ripening times of ethylene-treated bananas at 18&deg;C and 20&deg;C, which were about 5.5 and 4 days, respectively. In other words, bananas treated with ethylene ripen more slowly, not faster, at 14&deg;C and 16&deg;C than at 18&deg;C and 20&deg;C.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"040583a5","external_id":"d1d0c33d-ec34-4d8a-b2d4-4b8262f22cbc","vaultid":null,"uId":"0eb926dc-3464-4ac6-97c0-66f5f716ecf2","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<figure class=\"image\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"400\" height=\"478.4691162109375\" viewBox=\"0 0 400 478.4691162109375\" role=\"img\" aria-label=\"Bar graph titled Banana Ripening Time at Different Temperatures with and without Ethylene Treatment. The horizontal axis is labeled Temperature, in degrees Celsius. 4 data categories are shown. The vertical axis is labeled Time, in days. It ranges from 0 to 12 in increments of 1. Refer to long description.\"><g id=\"ed420550-79eb-48d4-af01-cd27cdd08afd\" data-name=\"Layer 1\"><defs>\n      <pattern id=\"bar4\" x=\"0\" y=\"0\" width=\"10\" height=\"100\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(50)\">\n        <rect x=\"0\" y=\"0\" width=\"5\" height=\"100\" fill=\"#CDCDCD\"/>\n        <rect x=\"5\" y=\"0\" width=\"5\" height=\"100\" fill=\"#444444\"/>\n      </pattern>\n    </defs><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"76.703125\" y1=\"96\" x2=\"385\" y2=\"96\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"70.703125\" y1=\"96\" x2=\"82.703125\" y2=\"96\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.9\"/><text text-